/**
 * Obtener la shape de una línea como GeoJSON Feature<LineString>.
 * @param label - Etiqueta visible (ej: "51", "M1", "N25")
 * @param direction - 0 o 1 (dirección GTFS)
 */
export function getRouteShape(label: string, direction: number = 0): GeoJSON.Feature<GeoJSON.LineString> | null {
  const key = `${label}_${direction}`;
  const coords = routeShapes[key];
  if (!coords || coords.length < 2) {
    // Intentar la otra dirección
    const altKey = `${label}_${direction === 0 ? 1 : 0}`;
    const altCoords = routeShapes[altKey];
    if (!altCoords || altCoords.length < 2) return null;
    return { type: "Feature", geometry: { type: "LineString", coordinates: altCoords }, properties: {} };
  }
  return { type: "Feature", geometry: { type: "LineString", coordinates: coords }, properties: {} };
}
